# Define the GSLVector class
class GSLVector:
    def __init__(self, size):
        self.size = size
        self.vector = gsl.gsl_vector_alloc(size)
        if not self.vector:
            raise MemoryError('Failed to allocate GSL vector')

    def set(self, index, value):
        if gsl.gsl_vector_set(self.vector, index, value) != 0:
            raise ValueError('Failed to set vector element')

    def get(self, index):
        return gsl.gsl_vector_get(self.vector, index)

    def __del__(self):
        if self.vector:
            gsl.gsl_vector_free(self.vector)

# Function to demonstrate the usage of GSLVector
def main():
    try:
        vector_size = 3
        vector = GSLVector(vector_size)
        vector.set(0, 1.0)
        vector.set(1, 2.0)
        vector.set(2, 3.0)
        value = vector.get(1)
        print(f'Retrieved value: {value}')
    except Exception as e:
        print(f'Error: {e}')

if __name__ == '__main__':
    main()

