import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = np.array(matrix, dtype=np.double)
        self.size = self.matrix.shape[0]

    def to_ctypes(self):
        return self.matrix.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

def is_positive_definite(matrix):
    try:
        np.linalg.cholesky(matrix)
        return True
    except np.linalg.LinAlgError:
        return False

def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite.")

    # Load the GSL libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Prepare the matrix
    gsl_matrix = GSLMatrix(matrix)
    gsl_matrix_ptr = gsl_matrix.to_ctypes()

    # Define the function prototype
    gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]

    # Perform Cholesky decomposition
    gsl.gsl_linalg_cholesky_decomp(gsl_matrix_ptr, gsl_matrix.size)

    # Extract the lower triangular matrix
    lower_triangular = np.tril(gsl_matrix.matrix)
    return lower_triangular.tolist()

