class GSLBlock:
    def __init__(self, n):
        self.n = n
        self.block = None

    def allocate(self):
        gsl_block_alloc = gsl.gsl_block_alloc
        gsl_block_alloc.restype = ctypes.POINTER(ctypes.c_double)
        self.block = gsl_block_alloc(self.n)
        return bool(self.block)

    def calloc(self):
        gsl_block_calloc = gsl.gsl_block_calloc
        gsl_block_calloc.restype = ctypes.POINTER(ctypes.c_double)
        self.block = gsl_block_calloc(self.n)
        return bool(self.block)

    def free(self):
        gsl_block_free = gsl.gsl_block_free
        gsl_block_free.argtypes = [ctypes.POINTER(ctypes.c_double)]
        gsl_block_free(self.block)

